public class SettingsCache {
    private static Map<String, Rate__c> rates;
    public static Map<String, Rate__c> getRates() {
        if (rates == null) {
            rates = new Map<String, Rate__c>();
            for (Rate__c r : [SELECT Name, Value__c FROM Rate__c]) {
                rates.put(r.Name, r);
            }
        }
        return rates;
    }
}

