trigger ContactTrg on Contact (before insert) {
    for (Contact c : Trigger.new) {
        Account a = [SELECT Industry FROM Account WHERE Id = :c.AccountId];
        c.Description = a.Industry;
    }
}

for (Opportunity o : Trigger.new) {
    List<Opportunity> opps = [SELECT Amount FROM Opportunity
        WHERE AccountId = :o.AccountId AND IsWon = true];
    Decimal total = 0;
    for (Opportunity x : opps) total += x.Amount;
    update new Account(Id = o.AccountId, Total_Won__c = total);
}

